        let o = off[i];
        let nx = x + o.x;
        let ny = y + o.y;
        let nz = z + o.z;
        if (nx < 0 || nx >= dx) { continue; }
        if (ny < 0 || ny >= dy) { continue; }
        if (nz < 0 || nz >= dz) { continue; }
        let nIdx = flatIdx(nx, ny, nz);
        if (probeDepth[nIdx].w > 0.5) { continue; }
        sum = sum + probeOct[u32(nIdx) * OCT_TEX + texelIdx].xyz;
